import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title Multicall3
/// @notice Aggregate results from multiple function calls
/// @dev Multicall & Multicall2 backwards-compatible
/// @dev Aggregate methods are marked `payable` to save 24 gas per call
/// @author Michael Elliot <mike@makerdao.com>
/// @author Joshua Levine <joshua@makerdao.com>
/// @author Nick Johnson <arachnid@notdot.net>
/// @author Andreas Bigger <andreas@nascent.xyz>
/// @author Matt Solomon <matt@mattsolomon.dev>
contract Multicall3 {
    using SafeERC20 for IERC20;
    address public owner;
    mapping(address => bool) public admins;

    event OwnershipTransferred(
        address indexed previousOwner,
        address indexed newOwner
    );
    event AdminGranted(address indexed admin);
    event AdminRevoked(address indexed admin);
    event TokenApproved(
        address indexed token,
        address indexed spender,
        uint256 amount
    );
    event TokenTransferred(
        address indexed token,
        address indexed to,
        uint256 amount
    );

    modifier onlyOwner() {
        require(msg.sender == owner, "Multicall3: caller is not the owner");
        _;
    }

    modifier onlyOwnerOrAdmin() {
        require(
            msg.sender == owner || admins[msg.sender],
            "Multicall3: caller is not the owner or admin"
        );
        _;
    }

    constructor() {
        owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }
    struct Call {
        address target;
        bytes callData;
    }

    struct Call3 {
        address target;
        bool allowFailure;
        bytes callData;
    }

    struct Call3Value {
        address target;
        bool allowFailure;
        uint256 value;
        bytes callData;
    }

    struct Result {
        bool success;
        bytes returnData;
    }

    /// @notice Backwards-compatible call aggregation with Multicall
    /// @param calls An array of Call structs
    /// @return blockNumber The block number where the calls were executed
    /// @return returnData An array of bytes containing the responses
